# Each chapter: id, icon, pages (route prefixes for the ? button), title(en,ta,hi), blurb(en,ta,hi), steps
# Each step: dict(target, route, act (dart code body using d.), t=(en,ta,hi), b=(en,ta,hi))
CH = []
def ch(id, icon, pages, title, blurb, steps): CH.append(dict(id=id, icon=icon, pages=pages, title=title, blurb=blurb, steps=steps))
def s(target, t, b, route=None, act=None): return dict(target=target, t=t, b=b, route=route, act=act)

